 viewer.openPdf(QString(TIGERSHEETS_SOURCE_DIR)+"/docs/validation/otis-90-minute/reference/101-01-Otis-10-K.pdf");find->setFocus();QTest::keyClick(find,Qt::Key_A,Qt::ControlModifier);QTest::keyRelease(find,Qt::Key_Control);QTest::keyClicks(find,"long-term debt");QTest::keyClick(find,Qt::Key_Return);QApplication::processEvents();require(viewer.observation().at("page")==16,"native search traverses actual PDF pages to its first long-term debt occurrence");QTest::keyClick(find,Qt::Key_Return);QApplication::processEvents();require(viewer.observation().at("page")==38,"repeated native Find advances to the second actual PDF occurrence");
